Page._content:
:root {
    --gutter: 25px;
    --radius: 13px;
    --color-primary: #22d9df;
    --color2: #a8ff3e;
    --color3: #e4a257;
    --color4: #33d57a;
    --color5: #00dbff;
    --color6: #1a98ff;
    --color7: #9090ff;
    --color-primary-bg: rgba(3, 155, 84, 0.15);
    --color2-bg: rgba(235, 172, 46, 0.176);
    --color3-bg: rgba(255,185,0,0.15);
    --color4-bg: rgba(51,213,122,0.15);
    --color5-bg: rgba(0,219,255,0.15);
    --color6-bg: rgba(26,152,255,0.15);
    --color7-bg: rgba(144,144,255,0.15);
    --color-shadow: rgba(161, 177, 204, 0.4);
}

.icon-home:before {
    content: "🏠";
    font-style: normal;
    font-weight: normal;
    font-size: 1.2em;
}

.icon-container:before {
    content: "📁";
    font-style: normal;
    font-weight: normal;
    font-size: 1.2em;
}

.icon-gallery:before {
    content: "🔭";
    font-style: normal;
    font-weight: normal;
    font-size: 1.2em;
}

.icon-info-circle:before {
    content: "ℹ";
    font-style: normal;
    font-weight: normal;
    font-size: 1.2em;
}

.icon-friends:before {
    content: "👫";
    font-style: normal;
    font-weight: normal;
    font-size: 1.2em;
}

.icon-sponsor:before {
    content: "💖";
    font-style: normal;
    font-weight: normal;
    font-size: 1.2em;
}

/* 侧边友情链接样式 */
.widget-friends {
    margin-bottom: 20px;
}

.widget-friends .widget-title {
    font-size: 1.1em;
    font-weight: bold;
    margin-bottom: 15px;
    color: #22d9df;
    border-bottom: 2px solid var(--primary-cyan);
    padding-bottom: 5px;
}

.friends-list {
    list-style: none;
    padding: 0 0 12px 0;
    margin: 0;
}

.friend-item {
    margin-bottom: 12px;
    padding: 8px;
    border-radius: 8px;
    min-height: 60px;
    display: flex;
    align-items: center;
}

.friend-link {
    display: flex;
    align-items: center;
    text-decoration: none;
    color: inherit;
    width: 100%;
}

.friend-link:hover {
    text-decoration: none;
    color: inherit;
}

.friend-avatar {
    width: 40px;
    height: 40px;
    border-radius: 50%;
    margin-right: 12px;
    object-fit: cover;
    border: 2px solid var(--primary-cyan);
    flex-shrink: 0;
}

.friend-info {
    flex: 1;
    display: flex;
    flex-direction: column;
    justify-content: center;
    min-width: 0;
}

.friend-name {
    font-weight: bold;
    color: var(--text-color);
    text-decoration: none;
    display: block;
    margin-bottom: 4px;
    font-size: 0.95em;
    line-height: 1.2;
}

.friend-desc {
    font-size: 0.85em;
    color: var(--text-muted);
    line-height: 1.3;
    word-wrap: break-word;
    overflow-wrap: break-word;
}

/* MathJax 数学公式样式 */
.MathJax {
    outline: 0;
}

.MathJax_Display {
    text-align: center !important;
    margin: 1em 0 !important;
}

.MathJax_SVG_Display {
    text-align: center !important;
    margin: 1em 0 !important;
}

/* 行内公式样式 */
.MathJax_SVG {
    display: inline !important;
    vertical-align: middle !important;
}

/* 块级公式样式 */
.MathJax_Display .MathJax_SVG {
    display: block !important;
    text-align: center !important;
}

/* 确保数学公式在暗色主题下可见 */
.MathJax_SVG * {
    color: inherit !important;
}

/* 数学公式容器样式 */
.math {
    text-align: center;
    margin: 1.2em 0;
}

/* 行内数学公式 */
.math.inline {
    display: inline;
    margin: 0;
}

/* 块级数学公式 */
.math.display {
    display: block;
    text-align: center;
    margin: 1.2em 0;
}
/* 横竖屏幕博客页显示优化 */
/* ===== 横屏显示优化 - 增加文章卡片高度 ===== */
@media screen and (orientation: landscape) and (min-width: 768px) {
    /* 增加文章卡片的最小高度 */
    .nexmoe-post,
    .post-card,
    .nexmoe-item {
        min-height: 420px !important;
    }

    /* 增加文章封面图片的高度比例 */
    .nexmoe-post-cover {
        padding-top: 50% !important;
    }
}

/* ===== 竖屏显示优化 - 增加文章卡片高度 ===== */
@media screen and (orientation: portrait) and (min-width: 768px) {
    /* 增加文章卡片的最小高度 */
    .nexmoe-post,
    .post-card,
    .nexmoe-item {
        min-height: 420px !important;
    }

    /* 增加文章封面图片的高度比例 */
    .nexmoe-post-cover {
        padding-top: 50% !important;
    }
}

