  node.begin(SENSOR_ADDR, rs485Serial);

  // 连接WiFi（带超时控制）
  Serial.print("连接WiFi: ");
  WiFi.begin(ssid, password);

  unsigned long start = millis();
  while (WiFi.status() != WL_CONNECTED && millis() - start < 15000) {
